violating:
import * as Atom from "effect/unstable/reactivity/Atom"
import { RegistryProvider, useAtom } from "@effect/atom-react"

const fahrenheitAtom = Atom.make(false)

type Sensor = {
  id: string
  label: string
  celsius: number
}

function TemperatureReading({ sensor }: { sensor: Sensor }) {
  const [fahrenheit] = useAtom(fahrenheitAtom)
  const value = fahrenheit ? sensor.celsius * 1.8 + 32 : sensor.celsius

  return (
    <li>
      <span>{sensor.label}</span>
      <output>{value.toFixed(1)} °{fahrenheit ? "F" : "C"}</output>
    </li>
  )
}

export function TemperaturePanel({ sensors }: { sensors: readonly Sensor[] }) {
  const [fahrenheit, setFahrenheit] = useAtom(fahrenheitAtom)

  return (
    <section aria-label="Cold storage temperatures">
      <label>
        <input
          type="checkbox"
          checked={fahrenheit}
          onChange={(event) => setFahrenheit(event.currentTarget.checked)}
        />
        Display all sensors in Fahrenheit
      </label>
      <ul>
        {sensors.map((sensor) => (
          <RegistryProvider key={sensor.id}>
            <TemperatureReading sensor={sensor} />
          </RegistryProvider>
        ))}
      </ul>
    </section>
  )
}

